mapper.select:
SELECT

id,

create_time, update_time,

organ_id, meta_name, model_id, permission_mode, status, remark,

delete_flag,

version
FROM data_permission_meta



        AND id = #{id, jdbcType=BIGINT}


        AND id IN

            #{item, jdbcType=BIGINT}





            AND create_time >= #{createTime[0], jdbcType=TIMESTAMP}


            AND create_time <= #{createTime[1], jdbcType=TIMESTAMP}


            AND create_time BETWEEN #{createTime[0], jdbcType=TIMESTAMP}
            AND #{createTime[1], jdbcType=TIMESTAMP}




            AND update_time >= #{updateTime[0], jdbcType=TIMESTAMP}


            AND update_time <= #{updateTime[1], jdbcType=TIMESTAMP}


            AND update_time BETWEEN #{updateTime[0], jdbcType=TIMESTAMP}
            AND #{updateTime[1], jdbcType=TIMESTAMP}




        AND organ_id = #{organId, jdbcType=BIGINT}


        AND meta_name = #{metaName, jdbcType=VARCHAR}


        AND model_id = #{modelId, jdbcType=BIGINT}


        AND permission_mode = #{permissionMode, jdbcType=TINYINT}


        AND status = #{status, jdbcType=VARCHAR}


        AND remark = #{remark, jdbcType=VARCHAR}


    AND (delete_flag = 0 OR delete_flag IS NULL)

SELECT meta.id AS meta_id, CASE WHEN meta.permission_mode = 0 AND EXISTS ( SELECT 1 FROM department d WHERE d.organ_id = #{organId, jdbcType=BIGINT} AND d.leader_user_id = #{userId, jdbcType=BIGINT} AND d.status = 'ACTIVE' AND d.delete_flag = 0 AND d.dept_path IN
#{deptPath, jdbcType=VARCHAR}
) THEN 2 ELSE meta.permission_mode END AS group_permission_mode, CAST(COALESCE(BIT_OR(other_rule.permission_mode), 0) AS SIGNED) AS other_permission_mode, GROUP_CONCAT( DISTINCT CONCAT('(', other_rule.permission_rule, ')') ORDER BY other_rule.id SEPARATOR ' OR ' ) AS permission_rule FROM data_permission_model model INNER JOIN data_permission_meta meta ON meta.model_id = model.id AND meta.organ_id = #{organId, jdbcType=BIGINT} AND meta.status = 'ACTIVE' AND meta.delete_flag = 0 LEFT JOIN ( SELECT DISTINCT g.id AS group_id FROM data_permission_group g INNER JOIN data_permission_group_user_relation gur ON gur.group_id = g.id AND gur.organ_id = g.organ_id AND gur.user_id = #{userId, jdbcType=BIGINT} AND gur.status = 'ACTIVE' AND gur.delete_flag = 0 WHERE g.organ_id = #{organId, jdbcType=BIGINT} AND g.status = 'ACTIVE' AND g.delete_flag = 0 AND g.dept_path IN
#{deptPath, jdbcType=VARCHAR}
) matched_group ON 1 = 1 LEFT JOIN data_permission_other other_rule ON other_rule.meta_id = meta.id AND other_rule.group_id = matched_group.group_id AND other_rule.status = 'ACTIVE' AND other_rule.delete_flag = 0 WHERE model.module_code = #{moduleCode, jdbcType=VARCHAR} AND model.table_name = #{tableName, jdbcType=VARCHAR} AND model.delete_flag = 0 GROUP BY meta.id, meta.permission_mode
